# Lecture 1, parts 3-4: the current ratio; the quick ratio and the cash ratio.
ALON_CA, ALON_CL = [120, 300, 480, 60], [330, 190, 80]
_alon_story = 'רהיטי אלון בע״מ מייצרת רהיטי עץ, ומוכרת אותם לרשתות ריהוט באשראי. בגיליון: הנכסים השוטפים וההתחייבויות השוטפות שלה ליום 31.12.2026, באלפי ש״ח.'


def _tca(n0=0, veil_inv=0, veil_rest=0):
    """Alon's current assets as a tower. n0: first click (0: all shown)."""
    k = lambda i: n0 + i if n0 else 0
    return [BK(k(0), 'מזומנים', '120', 'ca c0', 120), BK(k(1), 'לקוחות', '300', 'ca c1', 300, veil_rest), BK(k(2), 'מלאי', '480', 'ca c2', 480, veil_inv), BK(k(3), 'הוצאות מראש', '60', 'ca c3', 60, veil_rest)]


def _tcl(n0=0):
    k = lambda i: n0 + i if n0 else 0
    return [BK(k(0), 'ספקים', '330', 'cl', 330), BK(k(1), 'הלוואות לזמן קצר', '190', 'cl d1', 190), BK(k(2), 'הוצאות לשלם', '80', 'cl d2', 80)]


# ================================================================ part 3
opener(3, 'היחס השוטף', 'שאלת החלק: כמה שקלים של נכסים שוטפים עומדים מול כל שקל של התחייבויות שוטפות?',
       ['הרעיון: שני מגדלים, אחד מול השני', 'מסבירים יחד: היחס השוטף של רהיטי אלון', 'ההגדרה, ואיך קוראים את התוצאה', 'נסו לבד: רשת מזון', 'יתרונות וחסרונות'], 25)

S('s-cr-idea', 'הרעיון: שני מגדלים', 'הרעיון: מעמידים את כל הנכסים השוטפים מול כל ההתחייבויות השוטפות',
  RT(_tca(1), _tcl(5), [RES(8, 'נכסים שוטפים', '960', 'אלפי ש״ח'), RES(8, 'התחייבויות שוטפות', '600', 'אלפי ש״ח'), RES(9, 'אחד חלקי השני', '1.6', '', 'hot')], n_op=5)
  + BAND('dg', 'המגדל הימני גבוה פי 1.6 מהשמאלי. על כל 1 ש״ח של התחייבויות שוטפות, לרהיטי אלון יש 1.6 ש״ח של נכסים שוטפים.', 10), kick='חלק 3 · העיקרון')

